#release(directory: string): string[] {
	if (!existsSync(join(directory, "package.json"))) return ["no manifest"];
	try {
		return [
			"manifest",
			createHash("sha256")
				.update(readFileSync(join(directory, "package.json")))
				.digest("hex"),
		];
	} catch {
		this.#odd.push(this.#place(directory));
		return ["unreadable manifest"];
	}
}

